   if(W>0&&W%6==4){const j=me.pl.filter(p=>p.age<=20).sort((a,b)=>b.ovr-a.ovr)[0];if(j)mailAdd('c',`Promesa de la cantera: ${j.n}`,`Míster, ${j.n} (${j.age} años) viene destacando en las categorías inferiores. ${mailPick(['Tiene mucho margen de mejora.','Merece que le dé minutos cuando el partido lo permita.'])}\n\nSi quiere verlo de cerca, le invitamos a un entrenamiento.`)}
