mailF=x=>{const q=(S.mq||'').toLowerCase(),f=S.mf||'all';return(f=='all'||f=='un'&&!x.rd||f=='st'&&x.st||f==x.k)&&(!q||(x.s+' '+x.b+' '+mailWho(x.k)).toLowerCase().includes(q))};
